#pragma once
static void testMidiLoop(const juce::File& root){
 auto base=root.getChildFile("midi-loop");base.createDirectory();juce::Array<juce::var> results;
 for(int block:{128,256}){auto dir=base.getChildFile(juce::String(block));dir.createDirectory();Session s(dir);s.edit.reset();auto& hosted=s.engine.getDeviceManager().getHostedAudioDeviceInterface();te::HostedAudioDeviceInterface::Parameters params;params.sampleRate=48000;params.blockSize=block;params.inputChannels=0;params.outputChannels=2;hosted.initialise(params);hosted.prepareToPlay(48000,block);
  te::Edit::Options options{s.engine,te::createEmptyEdit(s.engine),te::ProjectItemID::createNewID(0)};options.role=te::Edit::forEditing;options.numAudioTracks=0;options.defaultMasterVolumedB=0;options.editFileRetriever=[&s]{return s.projectFile;};s.edit=std::make_unique<te::Edit>(options);auto* track=s.addTrack();auto clip=track->insertMIDIClip("Loop probe",{Session::time(0),Session::time(48000)},nullptr);require(clip!=nullptr,"Loop clip failed");auto beat=[](double n){return tracktion::BeatPosition::fromBeats(n);};clip->getSequence().addControllerEvent(beat(0.25),7,32<<7,nullptr);clip->getSequence().addControllerEvent(beat(0.375),te::MidiControllerEvent::pitchWheelType,16383,nullptr);clip->getSequence().addNote(60,beat(1),tracktion::BeatDuration::fromBeats(0.25),127,0,nullptr);
  juce::VST3PluginFormat format;juce::OwnedArray<juce::PluginDescription> types;format.findAllTypesForFile(types,juce::File(STUDIO_SOURCE_ROOT).getChildFile("build/backend/StudioMidiFixture_artefacts/Release/VST3/Studio MIDI Timing Fixture.vst3").getFullPathName());require(types.size()==1,"Loop instrument missing");PluginChain::add(s,0,*types[0]);
  juce::AudioBuffer<float> audio(2,block),captured(2,110000);captured.clear();juce::MidiBuffer midi;auto process=[&]{audio.clear();midi.clear();hosted.processBlock(audio,midi);juce::MessageManager::getInstance()->runDispatchLoopUntil(1);};for(int n=0;n<10;++n)process();auto& transport=s.edit->getTransport();transport.setLoopRange({Session::time(18000),Session::time(42000)});transport.looping=true;transport.setPosition(Session::time(18000));transport.play(false);
  for(int at=0;at+block<=captured.getNumSamples();at+=block){process();for(int c=0;c<2;++c)captured.copyFrom(c,at,audio,c,0,block);}juce::Array<int> edges;float error=0;bool sounding=false;float expected=0.001f*32/127*(1.0f+0.25f*8191/8192);
  for(int i=0;i<captured.getNumSamples();++i){float value=captured.getSample(0,i);bool current=value>1e-6f;if(current&&!sounding)edges.add(i);if(current)error=std::max(error,std::abs(value-expected));sounding=current;}
  require(edges.size()>=4&&error<1e-7f,"MIDI controller chase across loop differs");for(int i=1;i<edges.size();++i)require(std::abs(edges[i]-edges[i-1]-24000)<=1,"MIDI loop period differs");transport.stop(false,true);for(int n=0;n<30;++n)process();float stopped=0;for(int n=0;n<30;++n){process();stopped=std::max(stopped,audio.getMagnitude(0,block));}require(stopped<1e-7f,"Loop stop left held notes");
  auto* report=new juce::DynamicObject;report->setProperty("block",block);report->setProperty("cycles",edges.size());report->setProperty("controller_chase_error",error);report->setProperty("stop_peak",stopped);results.add(juce::var(report));
 }
 auto* report=new juce::DynamicObject;report->setProperty("checks",results.size());report->setProperty("cases",results);report->setProperty("physical_device_opened",false);base.getChildFile("midi-loop-result.json").replaceWithText(juce::JSON::toString(juce::var(report)));
}
